func TestCheckProxyAddr(t *testing.T) {
	proxy := func(addr string) services.Server {
		p := &services.ServerV2{}
		p.SetPublicAddr(addr)
		return p
	}
	tests := []struct {
		name     string
		config   *service.Config
		proxies  []services.Server
		override string
		want     string
		wantErr  bool
	}{
		{
			name: "local Kubernetes address",
			config: &service.Config{Proxy: service.ProxyConfig{
				PublicAddrs: []utils.NetAddr{{Addr: "proxy.example.com:3080"}},
				Kube:        service.KubeProxyConfig{Enabled: true, PublicAddrs: []utils.NetAddr{{Addr: "kube.example.com:443"}}},
			}},
			want: "https://kube.example.com:3026",
		},
		{
			name:    "registered proxy after invalid address",
			config:  &service.Config{},
			proxies: []services.Server{proxy("bad host:3080"), proxy("proxy.example.com:99999"), proxy("proxy.example.com:3080")},
			want:    "https://proxy.example.com:3026",
		},
		{
			name:    "no valid registered proxy",
			config:  &service.Config{},
			proxies: []services.Server{proxy("bad host:3080")},
			wantErr: true,
		},
		{
			name:     "explicit override",
			config:   &service.Config{Proxy: service.ProxyConfig{Kube: service.KubeProxyConfig{Enabled: true}}},
			override: "custom.example.com:1234",
			want:     "custom.example.com:1234",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ac := &AuthCommand{config: tt.config, outputFormat: identityfile.FormatKubernetes, proxyAddr: tt.override}
			err := ac.checkProxyAddr(mockClient{proxies: tt.proxies})
			if tt.wantErr {
				if err == nil {
					t.Fatal("expected error")
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if ac.proxyAddr != tt.want {
				t.Fatalf("got %q, want %q", ac.proxyAddr, tt.want)
			}
		})
	}
}

func TestAuthSignKubeconfig(t *testing.T) {
	tmpDir, err := ioutil.TempDir("", "auth_command_test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tmpDir)

	clusterName, err := services.NewClusterName(services.ClusterNameSpecV2{
		ClusterName: "example.com",
	})
	if err != nil {
		t.Fatal(err)
	}

	ca := services.NewCertAuthority(
		services.HostCA,
		"example.com",
		nil,
		[][]byte{[]byte("SSH CA cert")},
		nil,
		services.CertAuthoritySpecV2_RSA_SHA2_512,
	)
	ca.SetTLSKeyPairs([]services.TLSKeyPair{{Cert: []byte("TLS CA cert")}})

	client := mockClient{
		clusterName: clusterName,
		userCerts: &proto.Certs{
			SSH: []byte("SSH cert"),
			TLS: []byte("TLS cert"),
		},
		cas: []services.CertAuthority{ca},
	}
	ac := &AuthCommand{
		output:       filepath.Join(tmpDir, "kubeconfig"),
		outputFormat: identityfile.FormatKubernetes,
		proxyAddr:    "proxy.example.com",
	}

	// Generate kubeconfig.
	if err = ac.generateUserKeys(client); err != nil {
		t.Fatalf("generating kubeconfig: %v", err)
	}

	// Validate kubeconfig contents.
	kc, err := kubeconfig.Load(ac.output)
	if err != nil {
		t.Fatalf("loading generated kubeconfig: %v", err)
	}
	gotCert := kc.AuthInfos[kc.CurrentContext].ClientCertificateData
	if !bytes.Equal(gotCert, client.userCerts.TLS) {
		t.Errorf("got client cert: %q, want %q", gotCert, client.userCerts.TLS)
	}
	gotCA := kc.Clusters[kc.CurrentContext].CertificateAuthorityData
	wantCA := ca.GetTLSKeyPairs()[0].Cert
	if !bytes.Equal(gotCA, wantCA) {
		t.Errorf("got CA cert: %q, want %q", gotCA, wantCA)
	}
	gotServerAddr := kc.Clusters[kc.CurrentContext].Server
	if gotServerAddr != ac.proxyAddr {
		t.Errorf("got server address: %q, want %q", gotServerAddr, ac.proxyAddr)
	}
}

